CREATE TRIGGER hiring_webhook_revoke_audit AFTER UPDATE OF revoked_at ON hiring_webhook_subscriptions WHEN OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL BEGIN INSERT INTO hiring_audit_events(id,organization_id,brand_id,action,actor_user_id,operation_id,created_at) VALUES('webhook-revoke-'||NEW.id,NEW.organization_id,NEW.brand_id,'webhook.revoked',NEW.revoked_by,'webhook-revoke-'||NEW.id,NEW.revoked_at); END;
CREATE TRIGGER hiring_webhook_attempt_audit AFTER UPDATE OF state ON hiring_webhook_deliveries WHEN NEW.claim_id IS NOT NULL BEGIN INSERT INTO hiring_audit_events(id,organization_id,brand_id,action,actor_user_id,operation_id,created_at) SELECT 'webhook-attempt-'||NEW.id||'-'||NEW.attempts||'-'||NEW.state,s.organization_id,s.brand_id,'webhook.'||NEW.state,'system'||char(58)||'worker','webhook-attempt-'||NEW.id||'-'||NEW.attempts||'-'||NEW.state,NEW.claimed_at FROM hiring_webhook_subscriptions s WHERE s.id=NEW.subscription_id; END;

CREATE TABLE hiring_internship_requisitions(requisition_id TEXT PRIMARY KEY REFERENCES hiring_requisitions(id),organization_id TEXT NOT NULL,brand_id TEXT NOT NULL,onboarding_url TEXT NOT NULL,template_id TEXT NOT NULL,template_version INTEGER NOT NULL,configured_by TEXT NOT NULL,configured_at INTEGER NOT NULL);
CREATE TABLE hiring_internship_campaigns(id TEXT NOT NULL,requisition_id TEXT NOT NULL REFERENCES hiring_internship_requisitions(requisition_id),organization_id TEXT NOT NULL,brand_id TEXT NOT NULL,source_url TEXT NOT NULL,evidence TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),configured_by TEXT NOT NULL,configured_at INTEGER NOT NULL,PRIMARY KEY(id,requisition_id));
CREATE VIEW hiring_restricted_internships AS SELECT requisition_id FROM hiring_internship_requisitions UNION SELECT requisition_id FROM hiring_job_publications WHERE compensation_type='internship' UNION SELECT requisition_id FROM hiring_requisition_reviews WHERE json_extract(payload,'$.compensation_type')='internship';
CREATE TABLE hiring_internship_progress(operation_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,brand_id TEXT NOT NULL,requisition_id TEXT NOT NULL,application_id TEXT NOT NULL REFERENCES hiring_applications(id),status TEXT NOT NULL CHECK(status IN ('sourced','invited','onboarding_pending','active','exception')),reason_code TEXT NOT NULL,evidence TEXT NOT NULL CHECK(length(trim(evidence)) BETWEEN 1 AND 10000),discord_status TEXT NOT NULL CHECK(discord_status IN ('invite_pending','username_pending','joined')),discord_username TEXT NOT NULL,actor_user_id TEXT NOT NULL,created_at INTEGER NOT NULL,version INTEGER NOT NULL,UNIQUE(application_id,version));
CREATE TRIGGER hiring_internship_progress_validate BEFORE INSERT ON hiring_internship_progress BEGIN
SELECT RAISE(ABORT,'invalid internship progress') WHERE NEW.reason_code<>CASE NEW.status WHEN 'sourced' THEN 'source_verified' WHEN 'invited' THEN 'direct_invitation_sent' WHEN 'onboarding_pending' THEN 'interns_application_recorded' WHEN 'active' THEN 'interns_onboarding_verified' ELSE 'manual_exception' END OR (NEW.discord_status='joined' AND length(trim(NEW.discord_username))=0);
SELECT RAISE(ABORT,'invalid internship ordering') WHERE NOT ((NEW.version=1 AND NEW.status='sourced') OR (NEW.status='exception' AND NEW.version>1) OR EXISTS(SELECT 1 FROM hiring_internship_progress old WHERE old.application_id=NEW.application_id AND old.version=NEW.version-1 AND ((old.status='sourced' AND NEW.status='invited') OR (old.status='invited' AND NEW.status='onboarding_pending') OR (old.status='onboarding_pending' AND NEW.status='active'))));
SELECT RAISE(ABORT,'sent direct invitation required') WHERE NEW.status='invited' AND NOT EXISTS(SELECT 1 FROM hiring_outbox o JOIN hiring_internship_requisitions ir ON ir.requisition_id=NEW.requisition_id JOIN hiring_template_approvals t ON t.template_id=ir.template_id AND t.version=ir.template_version WHERE o.application_id=NEW.application_id AND o.organization_id=NEW.organization_id AND o.brand_id=NEW.brand_id AND o.delivery_state='sent' AND o.subject=t.subject AND o.body=t.body AND instr(o.body,ir.onboarding_url)>0) AND NOT EXISTS(SELECT 1 FROM hiring_worker_communication_events e JOIN hiring_internship_requisitions ir ON ir.requisition_id=NEW.requisition_id JOIN hiring_template_approvals t ON t.template_id=ir.template_id AND t.version=ir.template_version JOIN hiring_applications a ON a.id=NEW.application_id JOIN hiring_candidates c ON c.id=a.candidate_id WHERE e.application_id=NEW.application_id AND e.organization_id=NEW.organization_id AND e.brand_id=NEW.brand_id AND e.direction='outbound' AND e.to_email=c.email AND e.subject=t.subject AND e.body=t.body AND instr(e.body,ir.onboarding_url)>0);
END;
CREATE TRIGGER hiring_internship_no_interview BEFORE INSERT ON interviews WHEN EXISTS(SELECT 1 FROM hiring_applications a JOIN hiring_restricted_internships ir ON ir.requisition_id=a.requisition_id WHERE a.id=NEW.application_id) BEGIN SELECT RAISE(ABORT,'internships use direct Interns onboarding'); END;
CREATE TRIGGER hiring_internship_no_interview_stage BEFORE UPDATE OF stage,stage_extension ON hiring_applications WHEN (NEW.stage='interviewing' OR NEW.stage_extension='interviewing') AND (NEW.stage IS NOT OLD.stage OR NEW.stage_extension IS NOT OLD.stage_extension) AND EXISTS(SELECT 1 FROM hiring_restricted_internships WHERE requisition_id=NEW.requisition_id) BEGIN SELECT RAISE(ABORT,'internships use direct Interns onboarding'); END;
CREATE TRIGGER hiring_internship_requisitions_no_update BEFORE UPDATE ON hiring_internship_requisitions BEGIN SELECT RAISE(ABORT,'internship evidence is immutable'); END;
CREATE TRIGGER hiring_internship_requisitions_no_delete BEFORE DELETE ON hiring_internship_requisitions BEGIN SELECT RAISE(ABORT,'internship evidence is immutable'); END;
CREATE TRIGGER hiring_internship_progress_no_update BEFORE UPDATE ON hiring_internship_progress BEGIN SELECT RAISE(ABORT,'internship evidence is immutable'); END;
CREATE TRIGGER hiring_internship_progress_no_delete BEFORE DELETE ON hiring_internship_progress BEGIN SELECT RAISE(ABORT,'internship evidence is immutable'); END;
CREATE TRIGGER hiring_internship_progress_audit AFTER INSERT ON hiring_internship_progress BEGIN INSERT INTO hiring_audit_events(id,organization_id,brand_id,application_id,action,actor_user_id,operation_id,created_at) VALUES(NEW.operation_id,NEW.organization_id,NEW.brand_id,NEW.application_id,'internship.'||NEW.status,NEW.actor_user_id,NEW.operation_id,NEW.created_at); END;
CREATE TRIGGER hiring_internship_intake_guard BEFORE INSERT ON hiring_applications WHEN EXISTS(SELECT 1 FROM hiring_restricted_internships WHERE requisition_id=NEW.requisition_id) BEGIN SELECT RAISE(ABORT,'restricted internship intake') WHERE NOT EXISTS(SELECT 1 FROM hiring_internship_requisitions ir JOIN hiring_effective_access p ON p.organization_id=ir.organization_id AND p.brand_id=ir.brand_id WHERE ir.requisition_id=NEW.requisition_id AND ir.organization_id=NEW.organization_id AND ir.brand_id=NEW.brand_id AND p.user_id=NEW.created_by AND p.role IN ('owner','recruiter') AND (p.requisition_id IS NULL OR p.requisition_id=NEW.requisition_id)) OR NEW.idempotency_key IS NOT NULL; END;
